import os
import logging
import pkg_resources

from .. import builder
from abc import abstractmethod
from socket import gethostname, gethostbyname
from ute_btssm.filecollector.filecollector import FileCollector


class BaseCommand(object):
    def __init__(self):
        self._log = logging.getLogger(__name__)

    @abstractmethod
    def execute_command(self, operation, params, flags, filename=None, filepath=None, trs_ip=None, **kwargs):
        """ Execute tool operation except commissioning and swupdate
        :param string filename  Filename of the file. If None, default filename will be used
        :param string filepath  Path to file that was specified for BTSCommandLineTools. If None, log_path specified in setup will be used
        :param string operation BTSSM operation to be executed to be used(i.e. block)
        :param dict   params    Parameters needed for the tool command

        **kwarg values:
        :param string   alias  used to distinguish multiple library setup. Defaults to default
        :param integer timeout timeout to be used
        """

    @abstractmethod
    def execute_swupdate(self, operation, params, flags, filename=None, filepath=None, trs_ip=None, **kwargs):
        """ Execute swupdate tool operation
        :param string operation  tool operation used (i.e. swupdate)
        :param dict   params     Parameters needed for the tool command
        :param list   flags      Optional parameters to be added( i.e. waitforreset)
        :param string filename   Filename of the file. If None, default filename will be used
        :param string filepath   Path to file that was specified for BTSCommandLineTools. If None, log_path in setup will be used
        :return: Path to collected file
        :rtype list

        **kwarg values:
        :param string   alias   used to distinguish multiple library setup. Defaults to default
        :param integer timeout  timeout to be used
        """

    @abstractmethod
    def execute_commissioning(self, operation, params, flags, filename=None, filepath=None, trs_ip=None, **kwargs):
        """ Execute commissioning tool operation
        :param string operation   tool operation used (i.e. commission)
        :param dict   params      Parameters needed for the tool command
        :param list   flags       Optional parameters to be added( i.e. waitforreset)
        :param string filename    Filename of the file. If None, default filename will be used
        :param string filepath    Path to file that was specified for BTSCommandLineTools. If None, log_path in setup will be used
        :return: Path to collected file
        :rtype list

        **kwarg values:
        :param string   alias   used to distinguish multiple library setup. Defaults to default
        :param integer timeout  timeout to be used
        """

    @abstractmethod
    def get_config(self):
        """ Returns config """

    def _check_if_remote_host(self, host_ip):
        host_address = gethostname() + '.wroclaw.nsn-rdnet.net' if 'WRO' in host_ip else gethostname() + '.oulu.nsn-rdnet.net'
        return host_ip not in ['127.0.0.1', gethostbyname(gethostname()), host_address]

    def _rename(self, files_path, log_path, filename, executor):
        new_filename = os.path.join(log_path, filename + os.path.splitext(files_path)[1])
        executor.rename(files_path, new_filename)
        return new_filename

    def _path_to_collected_file(self, option, executor, log_path, trs_ip, filepath=None, filename=None, host_ip='127.0.0.1'):
        option = option[0] if len(option) > 0 else ''
        files_path = builder.CollectFilesPathBuilder(option=option, exec_path=log_path, executor=executor, trs_ip=trs_ip, filepath=filepath)
        files_path[0] = self._rename(files_path[0], log_path, filename, executor) if filename else files_path[0]
        [executor.get_file(file, file) for file in files_path if executor.file_exists(file) and self._check_if_remote_host(host_ip=host_ip)]
        files_path[0] = self._rename(files_path[0], log_path, filename, executor) if filename else files_path[0]
        return [item for item in files_path if executor.file_exists(item)]

    def _collect_cli_error_log_files(self, config, session):
        self._log.info("Contact BTSSM CLI TOOLS team if there are questions regarding the error. See BTSCommandLineTools wiki page "
                       "(https://twiki.int.net.nokia.com/bin/view/SEM/CommandlineTools) "
                       "given in the documentation for the contacts. Tool.log is needed to investigate on the issue.")
        fc = FileCollector(session.executor, tar_name='ErrorLogFiles.tar.gz')
        fc.get_files(files_list=['{}/ToolLog.xml'.format(config.log_path.rstrip('/')),
                                 '{}/PoseidonLog.xml'.format(config.log_path.rstrip('/')),
                                 '{}/Tool.log'.format(config.log_path.rstrip('/'))],
                     unzip=False,
                     subdirectory=None)

    def _get_commissioning_params(self, params, session):
        for key in params:
            if 'file' in key:
                new_path = session.executor.put_file(params[key], session.temp_dir)
                params[key] = new_path
                break
        return params

    def _create_symlink_file(self, symlink_file, session):
        if not session.executor.file_exists('{}{}{}'.format(session.log_path, os.path.sep, symlink_file)):
            conf_path = pkg_resources.resource_filename(__name__, "../resource{sep}{}".format(symlink_file, sep=os.path.sep))
            session.executor.run_ignoring_rc('ln -s "{}" "{}{}{}"'.format(conf_path, session.log_path, os.path.sep, symlink_file))
